{
  "name": "@bandonker/opencode-finish-guard",
  "version": "1.2.1",
  "description": "Normalises OpenAI-compatible SSE streams so a content or reasoning delta that arrives after the finish reason cannot kill a session (\"OpenAI Chat received content after the finish reason\"). A stream the gateway cuts mid-generation is left unterminated — never disguised as a clean stop — so it stays visible, counted, and re-attemptable.",
  "type": "module",
  "license": "MIT",
  "main": "./index.js",
  "exports": {
    ".": "./index.js",
    "./server": "./index.js"
  },
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "stream",
    "sse",
    "provider",
    "openai",
    "compatibility"
  ],
  "homepage": "https://github.com/Bandonker/open-toolbox",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Bandonker/open-toolbox.git"
  },
  "bugs": "https://github.com/Bandonker/open-toolbox/issues",
  "engines": {
    "node": ">=20"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.11"
  },
  "dependencies": {
    "zod": "4.1.8"
  }
}
